const body = $input.item.json.body || $input.item.json;
const staticData = $getWorkflowStaticData('global');

// Guardar todos los campos de configuracion que lleguen
const campos = [
  'PULSE_API_KEY','PULSE_DEVICE_ID',
  'LUZ_UMBRAL_DIA','LUZ_UMBRAL_NOCHE','LUZ_MINUTOS_CONFIRMACION',
  'DIA_VPD_MIN','DIA_VPD_MAX','DIA_VPD_OBJ',
  'NOCHE_VPD_MIN','NOCHE_VPD_MAX','NOCHE_VPD_OBJ',
  'PULSO_HUMIDIFICADOR_SEG','PULSO_EXTRACTOR_SEG',
  'ESPERA_ENTRE_PULSOS_MIN','TIEMPO_OBSERVACION_MIN',
  'EMAIL_NOTIFICACIONES',
  'EXTRACTOR_DEVICE_ID','HUMIDIFICADOR_DEVICE_ID'
];

campos.forEach(campo => {
