    staticData[campo] = body[campo];
  }
});
staticData.config_actualizada = new Date().toISOString();

console.log('Config actualizada desde dashboard:', JSON.stringify(staticData));
return [{ json: { ok: true, mensaje: 'Configuracion guardada en n8n', timestamp: staticData.config_actualizada } }];

const crypto = require('crypto');
const body = $input.item.json.body || $input.item.json;
const staticData = $getWorkflowStaticData('global');

const EXTRACTOR_DEVICE_ID     = staticData.EXTRACTOR_DEVICE_ID     || 'eb3f3f71899e5e41e5g66y';
const HUMIDIFICADOR_DEVICE_ID = staticData.HUMIDIFICADOR_DEVICE_ID || 'eb8fed679bbe9ca2ffqate';
const CLIENT_ID = 'rkpuumd4n53ygdhewc54';
const SECRET    = '84c0dad687e8491796db4cb0aa32e591';

const device = body.device;
const state  = body.state;
const device_id = device === 'extractor' ? EXTRACTOR_DEVICE_ID : HUMIDIFICADOR_DEVICE_ID;

const ts = Date.now().toString();
const contentHash = crypto.createHash('sha256').update('').digest('hex');
const str = CLIENT_ID + ts + 'GET\n' + contentHash + '\n\n/v1.0/token?grant_type=1';
const sign = crypto.createHmac('sha256', SECRET).update(str).digest('hex').toUpperCase();

return [{ json: {
  device_id,
  device_nombre: device,
  state,
  TUYA_CLIENT_ID: CLIENT_ID,
  TUYA_SECRET: SECRET,
  tuya_ts: ts,
  tuya_sign: sign
}}];

const crypto = require('crypto');
const tokenData = $input.item.json;
const ctrl = $('Preparar Control Manual').item.json;

if (!tokenData.success) throw new Error('Token Tuya fallido: ' + JSON.stringify(tokenData));

