const config = $('CONFIGURACION').item.json;
const data = $input.item.json;

const temperatura = data.temperatureC;
const humedad = data.humidityRh;
const luz = data.lightLux ?? 0;

if (temperatura === undefined || temperatura === null) throw new Error('No se encontro temperatureC.');
if (humedad === undefined || humedad === null) throw new Error('No se encontro humidityRh.');

function calcSVP(tempC) {
  return 0.6108 * Math.exp((17.27 * tempC) / (tempC + 237.3));
}
const svp_actual = calcSVP(temperatura);
const vpd_actual = parseFloat(((1 - humedad / 100) * svp_actual).toFixed(3));

const staticData = $getWorkflowStaticData('global');
const ahora = Date.now();

const modo_actual = luz >= config.LUZ_UMBRAL_DIA ? 'dia' : 'noche';

const VPD_MIN = modo_actual === 'dia' ? config.DIA_VPD_MIN : config.NOCHE_VPD_MIN;
const VPD_MAX = modo_actual === 'dia' ? config.DIA_VPD_MAX : config.NOCHE_VPD_MAX;
const VPD_OBJ = modo_actual === 'dia' ? config.DIA_VPD_OBJ : config.NOCHE_VPD_OBJ;

let humidificador_prendido_en = staticData.humidificador_prendido_en !== undefined ? staticData.humidificador_prendido_en : null;
let extractor_prendido_en     = staticData.extractor_prendido_en !== undefined ? staticData.extractor_prendido_en : null;
let historial                 = staticData.historial || [];

let extractor_accion     = null;
let humidificador_accion = null;
let notificaciones       = [];

if (extractor_prendido_en !== null && vpd_actual >= VPD_OBJ) {
  extractor_accion      = false;
  extractor_prendido_en = null;
  const ev = { dispositivo: 'Extractor', accion: 'APAGADO', vpd: vpd_actual, temp: temperatura, hr: humedad, modo: modo_actual, timestamp: new Date(ahora).toISOString() };
  historial.push(ev); notificaciones.push(ev);
}

if (humidificador_prendido_en !== null && vpd_actual <= VPD_OBJ) {
  humidificador_accion      = false;
  humidificador_prendido_en = null;
  const ev = { dispositivo: 'Humidificador', accion: 'APAGADO', vpd: vpd_actual, temp: temperatura, hr: humedad, modo: modo_actual, timestamp: new Date(ahora).toISOString() };
  historial.push(ev); notificaciones.push(ev);
}

const ambos_apagados        = humidificador_prendido_en === null && extractor_prendido_en === null;
const nadie_acaba_de_actuar = humidificador_accion === null && extractor_accion === null;

if (ambos_apagados && nadie_acaba_de_actuar) {
  const vpd_alto = vpd_actual > VPD_MAX;
  const vpd_bajo = vpd_actual < VPD_MIN;

  if (vpd_alto) {
    humidificador_accion      = true;
    humidificador_prendido_en = ahora;
    const ev = { dispositivo: 'Humidificador', accion: 'ENCENDIDO', vpd: vpd_actual, temp: temperatura, hr: humedad, modo: modo_actual, timestamp: new Date(ahora).toISOString() };
    historial.push(ev); notificaciones.push(ev);
  } else if (vpd_bajo) {
    extractor_accion      = true;
    extractor_prendido_en = ahora;
    const ev = { dispositivo: 'Extractor', accion: 'ENCENDIDO', vpd: vpd_actual, temp: temperatura, hr: humedad, modo: modo_actual, timestamp: new Date(ahora).toISOString() };
    historial.push(ev); notificaciones.push(ev);
  }
}

if (historial.length > 100) historial = historial.slice(-100);

staticData.humidificador_prendido_en = humidificador_prendido_en;
staticData.extractor_prendido_en     = extractor_prendido_en;
staticData.historial                 = historial;

console.log(`MODO: ${modo_actual} | Luz: ${luz} | Temp: ${temperatura}C | HR: ${humedad}% | VPD: ${vpd_actual} kPa`);
console.log(`Rango: ${VPD_MIN}-${VPD_MAX} | Objetivo corte: ${VPD_OBJ}`);

return [{ json: {
  PULSE_API_KEY:           config.PULSE_API_KEY,
  PULSE_DEVICE_ID:         config.PULSE_DEVICE_ID,
  EXTRACTOR_DEVICE_ID:     config.EXTRACTOR_DEVICE_ID,
  HUMIDIFICADOR_DEVICE_ID: config.HUMIDIFICADOR_DEVICE_ID,
  SWITCHES_EXTRA:          config.SWITCHES_EXTRA,
  TUYA_CLIENT_ID:          'rkpuumd4n53ygdhewc54',
  TUYA_SECRET:             '84c0dad687e8491796db4cb0aa32e591',
  EMAIL_NOTIFICACIONES:    config.EMAIL_NOTIFICACIONES,
  modo_actual,
  temperatura,
  humedad,
  luz,
  vpd_actual,
  vpd_objetivo: VPD_OBJ,
  vpd_min:      VPD_MIN,
  vpd_max:      VPD_MAX,
  extractor_accion,
  humidificador_accion,
  notificaciones,
  historial,
  switches_extra_acciones: []
}}];

