const crypto = require('crypto');
const tokenData = $input.item.json;
const config = $('Logica de Decision').item.json;

if (!tokenData.success) {
  throw new Error('Error obteniendo token Tuya: ' + JSON.stringify(tokenData));
}

const CLIENT_ID = config.TUYA_CLIENT_ID;
const SECRET = config.TUYA_SECRET;
const tuya_token = tokenData.result.access_token;

const comandos = [];
if (config.extractor_accion !== null) {
  comandos.push({ device_id: config.EXTRACTOR_DEVICE_ID, nombre: 'Extractor', estado: config.extractor_accion });
}
if (config.humidificador_accion !== null) {
  comandos.push({ device_id: config.HUMIDIFICADOR_DEVICE_ID, nombre: 'Humidificador', estado: config.humidificador_accion });
}

if (comandos.length === 0) {
  return [{ json: { sin_accion: true, vpd_actual: config.vpd_actual, modo: config.modo_actual, mensaje: 'VPD en rango, sin comandos' } }];
}

const requests = comandos.map(cmd => {
  const BODY = JSON.stringify({ commands: [{ code: 'switch_1', value: cmd.estado }] });
  const ts = Date.now().toString();
  const path = `/v1.0/devices/${cmd.device_id}/commands`;
  const bodyHash = crypto.createHash('sha256').update(BODY).digest('hex');
  const str = CLIENT_ID + tuya_token + ts + 'POST\n' + bodyHash + '\n\n' + path;
  const sign = crypto.createHmac('sha256', SECRET).update(str).digest('hex').toUpperCase();
  return {
    nombre: cmd.nombre,
    estado: cmd.estado ? 'ENCENDIDO' : 'APAGADO',
    url: `https://openapi.tuyaus.com${path}`,
    body: BODY,
    header_client_id: CLIENT_ID,
    header_token: tuya_token,
    header_t: ts,
    header_sign: sign
  };
});

return requests.map(r => ({ json: r }));
